<h1>Restore JSON Backup</h1>
<p>Restore a JSON backup exported by the journal. Existing tickets for the selected account are skipped.</p>
<form method="post" enctype="multipart/form-data" class="card"><?=csrf_field()?><p><label>Account</label><select name="account_id" required><?php foreach($accounts as $a):?><option value="<?=$a['id']?>"><?=e($a['name'])?> (<?=e($a['currency'])?>)</option><?php endforeach;?></select></p><p><label>JSON backup</label><input type="file" name="json_file" accept="application/json,.json" required></p><div class="actions"><button name="action" value="preview" class="secondary">Preview</button><button name="action" value="import">Restore</button></div></form>
<?php if($preview):?><div class="card"><h2>Preview</h2><p>Total: <strong><?=e($preview['total'])?></strong> · Valid: <strong><?=e($preview['valid'])?></strong> · Duplicates: <strong><?=e($preview['duplicates'])?></strong> · Errors: <strong><?=count($preview['errors'])?></strong></p><?php if($preview['errors']):?><ul><?php foreach($preview['errors'] as $e):?><li><?=e($e)?></li><?php endforeach;?></ul><?php endif;?></div><?php endif;?>
